use atlas_native_storage_contract::{create_workspace,execute,save_note_draft,get_note_draft,clear_note_draft};
#[test]fn draft_is_durable_but_does_not_change_search(){let root=std::env::temp_dir().join(format!("atlas-draft-{}",uuid::Uuid::new_v4()));create_workspace(&root).unwrap();let args=vec!["atlas".into(),"create-note".into(),root.to_string_lossy().into_owned(),"before".into(),"olduniqueword".into()];let id=execute(&args).unwrap()["id"].as_str().unwrap().to_owned();save_note_draft(&root,&id,"after","newuniqueword").unwrap();assert_eq!(get_note_draft(&root,&id).unwrap(),Some(("after".into(),"newuniqueword".into())));let db=rusqlite::Connection::open(root.join("atlas.sqlite3")).unwrap();let old:i64=db.query_row("SELECT count(*) FROM search_index WHERE search_index MATCH 'olduniqueword'",[],|r|r.get(0)).unwrap();let new:i64=db.query_row("SELECT count(*) FROM search_index WHERE search_index MATCH 'newuniqueword'",[],|r|r.get(0)).unwrap();assert_eq!((old,new),(1,0));drop(db);assert!(!clear_note_draft(&root,&id,"after","other").unwrap());assert!(get_note_draft(&root,&id).unwrap().is_some());assert!(clear_note_draft(&root,&id,"after","newuniqueword").unwrap());std::fs::remove_dir_all(root).unwrap();}
#[test]fn export_never_silently_discards_draft(){let root=std::env::temp_dir().join(format!("atlas-draft-export-{}",uuid::Uuid::new_v4()));create_workspace(&root).unwrap();let args=vec!["atlas".into(),"create-note".into(),root.to_string_lossy().into_owned(),"title".into(),"old".into()];let id=execute(&args).unwrap()["id"].as_str().unwrap().to_owned();save_note_draft(&root,&id,"title","draft").unwrap();let dest=root.with_extension("copy");assert!(atlas_native_storage_contract::snapshot_workspace(&root,&dest).is_err());assert!(!dest.exists());assert!(get_note_draft(&root,&id).unwrap().is_some());assert_eq!(atlas_native_storage_contract::recover_note_drafts(&root).unwrap(),1);assert_eq!(atlas_native_storage_contract::recover_note_drafts(&root).unwrap(),0);assert!(get_note_draft(&root,&id).unwrap().is_none());std::fs::remove_dir_all(root).unwrap();}
#[test]fn trashed_draft_survives_export_and_undo(){let root=std::env::temp_dir().join(format!("atlas-draft-trash-{}",uuid::Uuid::new_v4()));create_workspace(&root).unwrap();let args=vec!["atlas".into(),"create-note".into(),root.to_string_lossy().into_owned(),"old title".into(),"oldword".into()];let id=execute(&args).unwrap()["id"].as_str().unwrap().to_owned();save_note_draft(&root,&id,"new title","restoreduniqueword").unwrap();atlas_native_storage_contract::delete_objects(&root,&[id.clone()]).unwrap();let dest=root.with_extension("copy");atlas_native_storage_contract::snapshot_workspace(&root,&dest).unwrap();for path in [&root,&dest]{assert_eq!(get_note_draft(path,&id).unwrap().unwrap().1,"restoreduniqueword");let board=atlas_native_storage_contract::restore_objects(path,&[id.clone()]).unwrap();assert_eq!(board["objects"][0]["title"],"new title");assert!(get_note_draft(path,&id).unwrap().is_none());let db=rusqlite::Connection::open(path.join("atlas.sqlite3")).unwrap();let n:i64=db.query_row("SELECT count(*) FROM search_index WHERE search_index MATCH 'restoreduniqueword'",[],|r|r.get(0)).unwrap();assert_eq!(n,1);}std::fs::remove_dir_all(root).unwrap();std::fs::remove_dir_all(dest).unwrap();}
